chrome.runtime.onInstalled.addListener(()=>{console.log("AI Job Search & Application Assistant installed."),chrome.alarms.create("checkReminders",{periodInMinutes:30})});chrome.alarms.onAlarm.addListener(e=>{e.name==="checkReminders"&&chrome.storage.local.get(["settings"],n=>{n.settings&&n.settings.token&&console.log("Checking pending follow-ups...")})});chrome.runtime.onMessage.addListener((e,n,t)=>(e.action==="OPEN_DASHBOARD"&&(chrome.tabs.create({url:chrome.runtime.getURL("src/dashboard/index.html")}),t({status:"ok"})),!0));
